def feature(s):
    sites = s.get('sites', ())
    best = [math.inf for t in sites]
    for b in s.get('neighbors', ()):
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0 and (sites[b['j']].get('occupancy') or 0.0) > 0:
            best[b['i']] = min(best[b['i']], d)
    total = 0.0
    square = 0.0
    weight = 0.0
    for i, t in enumerate(sites):
        o = t.get('occupancy') or 0.0
        if o > 0 and math.isfinite(best[i]):
            total += o * best[i]
            square += o * best[i] * best[i]
            weight += o
    if weight <= 0 or total <= 0:
        return 0.0
    mean = total / weight
    return float(math.sqrt(max(0.0, square / weight - mean * mean)) / mean)

def feature(s):
    sites = s.get('sites', ())
    neighbors = s.get('neighbors', ())
    occ = [max(0.0, t.get('occupancy') or 0.0) for t in sites]
    nearest = [math.inf for t in sites]
    for b in neighbors:
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0 and occ[b['j']] > 0:
            nearest[b['i']] = min(nearest[b['i']], d)
    cn = [0.0 for t in sites]
    for b in neighbors:
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0 and d <= 1.25 * nearest[b['i']]:
            cn[b['i']] += occ[b['j']]
    w = sum(occ)
    return float(sum(occ[i] * cn[i] for i in range(len(sites))) / w) if w > 0 else 0.0

