def feature(s):
    sites = s.get('sites', ())
    neighbors = s.get('neighbors', ())
    occ = [max(0.0, t.get('occupancy') or 0.0) for t in sites]
    nearest = [math.inf for t in sites]
    for b in neighbors:
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0 and occ[b['j']] > 0:
            nearest[b['i']] = min(nearest[b['i']], d)
    unlike = 0.0
    weight = 0.0
    for b in neighbors:
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0 and d <= 1.25 * nearest[i]:
            w = occ[i] * occ[j]
            weight += w
            if sites[i].get('element') != sites[j].get('element'):
                unlike += w
    fractions = [x for x in s.get('composition', {}).values() if x is not None and math.isfinite(x) and x > 0]
    z = sum(fractions)
    if weight <= 0 or z <= 0:
        return 0.0
    expected = 1.0 - sum((x / z) ** 2 for x in fractions)
    return float(unlike / weight - expected)

def feature(s):
    sites = s.get('sites', ())
    neighbors = s.get('neighbors', ())
    occ = [max(0.0, t.get('occupancy') or 0.0) for t in sites]
    first = [math.inf for t in sites]
    second = [math.inf for t in sites]
    for b in neighbors:
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0 and occ[b['j']] > 0:
            first[b['i']] = min(first[b['i']], d)
    for b in neighbors:
        i = b['i']
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 1.15 * first[i] and occ[b['j']] > 0:
            second[i] = min(second[i], d)
    total = 0.0
    weight = 0.0
    for i in range(len(sites)):
        if occ[i] > 0 and math.isfinite(first[i]) and math.isfinite(second[i]):
            total += occ[i] * second[i] / first[i]
            weight += occ[i]
    return float(total / weight) if weight > 0 else 0.0
